import java.util.*;

class Solution {
    public String smallestSubsequence(String text) {
        int[] last = new int[26];
        for (int i = 0; i < text.length(); i++) last[text.charAt(i) - 'a'] = i;
        boolean[] used = new boolean[26];
        StringBuilder st = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (used[c - 'a']) continue;
            // pop bigger letters that we can still pick up later
            while (st.length() > 0 && st.charAt(st.length() - 1) > c
                    && last[st.charAt(st.length() - 1) - 'a'] > i) {
                used[st.charAt(st.length() - 1) - 'a'] = false;
                st.deleteCharAt(st.length() - 1);
            }
            st.append(c);
            used[c - 'a'] = true;
        }
        return st.toString();
    }
}

