class Solution:
    def smallestSubsequence(self, text: str) -> str:
        remain = Counter(text); st = []; used = set()
        for c in text:
            remain[c] -= 1
            if c in used: continue
            while st and st[-1] > c and remain[st[-1]] > 0: used.discard(st.pop())
            st.append(c); used.add(c)
        return "".join(st)

