function smallestSubsequence(text) {
  const last = {}; for (let i = 0; i < text.length; i++) last[text[i]] = i;
  const st = [], used = new Set();
  for (let i = 0; i < text.length; i++) {
    const c = text[i]; if (used.has(c)) continue;
    while (st.length && st[st.length - 1] > c && last[st[st.length - 1]] > i) used.delete(st.pop());
    st.push(c); used.add(c);
  }
  return st.join("");
}
